// Command goqueryset generates typed GORM v2 query sets for the structs of one Go file that carry a "gen:qs" comment
// line. Use it from go:generate next to the models:
//
//	// gen:qs
//	//
//	//go:generate go run github.com/anvh2/go-kit/cmd/goqueryset -in farm.go -out autogenerated_farm.gen.go
//	type Farm struct { ... }
package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/anvh2/go-kit/cmd/goqueryset/generator"
)

func main() {
	in := flag.String("in", "", "Go source file with the annotated models (required)")
	out := flag.String("out", "", "output file (required)")
	flag.Parse()
	if *in == "" || *out == "" {
		flag.Usage()
		os.Exit(2)
	}
	if err := run(*in, *out); err != nil {
		fmt.Fprintln(os.Stderr, "goqueryset:", err)
		os.Exit(1)
	}
}

func run(in, out string) error {
	src, err := os.ReadFile(in)
	if err != nil {
		return err
	}
	code, err := generator.Generate(in, src)
	if err != nil {
		return err
	}
	return os.WriteFile(out, code, 0o644)
}
